"""OMNIMIND benchmark, lane ZF, family `cross`: the freeze of the pair table and of the generated bytes, every truth
re-derived from the bytes by readers written here against the file formats (not by calling the generators), the twins
differing in exactly one value, and the scoring of the references (always "consistent" scores exactly one half)."""
import ast
import csv
from decimal import Decimal
import hashlib
import io
import json
import math
from pathlib import Path
import re
import struct
import wave
import xml.etree.ElementTree as ET
import zipfile

import pytest

from neuroscifi.acceptance.omni import cross, cross_cases

CROSS_CASES_SHA256 = "f52dff297dbf02b79edd9bcdd08ea7266a50ef37fba3df8c5aac3199f31ffb70"
GENERATED_SHA256 = {"development": "6d17d45bf4d2907d4b21e8ce1971d5ed0c04fcbb9d9b44774fef94bf122984c1",
                    "held_out": "409b442cf6b6f6afcef07951ace9c0b9ad20705b4f6fec9932931388afb88555"}
SVG = "{http://www.w3.org/2000/svg}"


def _pairs(split):
    return {p["id"]: p for p in cross_cases.ALL[split]}


# ---- readers (independent of cross.py) --------------------------------------------------------------------------------

def _text_of(name, data):
    if name.endswith(".docx"):
        with zipfile.ZipFile(io.BytesIO(data)) as z:
            root = ET.fromstring(z.read("word/document.xml"))
        return "\n".join("".join(t.text or "" for t in p.iter() if t.tag.endswith("}t"))
                         for p in root.iter() if p.tag.endswith("}p"))
    return data.decode("utf-8")


def _number(text, style):
    text = text.strip().lstrip("$£€")
    if style == "euro":
        return Decimal(text.replace(".", "").replace(",", "."))
    return Decimal(text.replace(",", ""))


def read_report_total(pair, files):
    k = pair["knobs"]
    report = _text_of(k["report"], files[k["report"]])
    prefix = k["sentence"].split("{total}")[0]
    tail = report[report.index(prefix) + len(prefix):]
    stated = _number(re.match(r"[$£€]?[0-9][0-9.,]*[0-9]|[$£€]?[0-9]", tail).group(0), k["style"])
    rows = list(csv.reader(io.StringIO(files[k["csv"]].decode("utf-8")),
                           delimiter=";" if k["style"] == "euro" else ","))
    values = [_number(r[1], k["style"]) for r in rows[1:]]
    return stated, values


def read_chart(pair, files):
    k = pair["knobs"]
    root = ET.fromstring(files[k["svg"]])

    def translate(g):
        x, y = re.match(r"translate\(([-0-9.]+),([-0-9.]+)\)", g.get("transform")).groups()
        return float(x), float(y)
    axis_y = next(g for g in root.iter(SVG + "g") if g.get("class") == "axis y")
    ticks = [(translate(t)[1], float(t.find(SVG + "text").text)) for t in axis_y if t.get("class") == "tick"]
    (p0, v0), (p1, v1) = ticks[0], ticks[-1]
    mid_p, mid_v = ticks[len(ticks) // 2]
    linear_guess = v0 + (mid_p - p0) / (p1 - p0) * (v1 - v0)
    assert len(ticks) >= 3                                       # two ticks cannot tell linear from log
    is_log = abs(linear_guess - mid_v) > 0.01 * abs(v1 - v0)
    if is_log:
        def value(py):
            return 10 ** (math.log10(v0) + (py - p0) / (p1 - p0) * (math.log10(v1) - math.log10(v0)))
    else:
        def value(py):
            return v0 + (py - p0) / (p1 - p0) * (v1 - v0)
    plot = next(g for g in root.iter(SVG + "g") if g.get("class") == "plot")
    ys = []
    for el in plot.iter():
        if el.tag == SVG + "polyline":
            ys = [float(pt.split(",")[1]) for pt in el.get("points").split()]
        elif el.tag == SVG + "circle":
            ys.append(float(el.get("cy")))
        elif el.tag == SVG + "rect":
            ys.append(float(el.get("y")))
    plotted = [value(y) for y in ys]
    rows = list(csv.reader(io.StringIO(files[k["csv"]].decode("utf-8"))))
    tabled = [float(r[1]) for r in rows[1:]]
    return plotted, tabled


def read_tones(pair, files):
    k = pair["knobs"]
    with wave.open(io.BytesIO(files[k["wav"]])) as w:
        assert (w.getnchannels(), w.getsampwidth()) == (1, 2)
        rate = w.getframerate()
        samples = struct.unpack(f"<{w.getnframes()}h", w.readframes(w.getnframes()))
    quiet_needed = int(0.01 * rate)
    tones, quiet, inside = 0, quiet_needed, False
    for s in samples:
        if abs(s) > 300:
            if not inside and quiet >= quiet_needed:
                tones += 1
            inside, quiet = True, 0
        else:
            quiet += 1
            if quiet >= quiet_needed:
                inside = False
    rows = list(csv.reader(io.StringIO(files[k["csv"]].decode("utf-8"))))
    return tones, len(rows) - 1


def read_mesh(pair, files):
    k = pair["knobs"]
    text = files[k["obj"]].decode("utf-8")
    unit = re.search(r"# units: (\w+)", text).group(1)
    to_mm = {"millimetres": 1.0, "centimetres": 10.0, "metres": 1000.0}[unit]
    verts = [[float(x) * to_mm for x in line.split()[1:4]] for line in text.splitlines() if line.startswith("v ")]
    lo = [min(v[i] for v in verts) for i in range(3)]
    hi = [max(v[i] for v in verts) for i in range(3)]
    readme = files[k["readme"]].decode("utf-8")
    num = r"(-?[0-9.]+)"
    m = re.search(rf"Overall size: {num} x {num} x {num} mm", readme)
    if m:
        stated = ("size", [float(x) for x in m.groups()])
    else:
        m = re.search(rf"x {num} to {num}, y {num} to {num}, z {num} to {num}", readme)
        if m:
            g = [float(x) for x in m.groups()]
            stated = ("minmax", [g[0], g[2], g[4], g[1], g[3], g[5]])
        else:
            m = re.search(rf"{num} mm wide, {num} mm deep and {num} mm tall", readme)
            stated = ("size", [float(x) for x in m.groups()])
    actual = [h - low for h, low in zip(hi, lo)] if stated[0] == "size" else lo + hi
    return stated[1], actual


def read_trace(pair, files):
    k = pair["knobs"]
    tree = ast.parse(files[k["py"]].decode("utf-8"))
    calls = {}
    for fn in tree.body:
        if isinstance(fn, ast.FunctionDef):
            calls[fn.name] = {n.func.id for n in ast.walk(fn) if isinstance(n, ast.Call)
                              and isinstance(n.func, ast.Name)}
    trace = json.loads(files[k["trace"]])
    edges, names = [], []
    if "events" in trace:
        edges = [(e["caller"], e["callee"]) for e in trace["events"]]
        names = list(edges)
    else:
        def walk(node):
            names.append(node["function"])
            for child in node["calls"]:
                edges.append((node["function"], child["function"]))
                walk(child)
        walk(trace["root"])
    return calls, edges, names


_SYSLOG = re.compile(r"^(\w{3}) +(\d+) (\d\d:\d\d:\d\d) \S+ [^:]+: (.*)$")
_ISO = re.compile(r"^(\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ) \w+ [^:]+: (.*)$")


def read_timeline(pair, files):
    k = pair["knobs"]
    doc = files[k["doc"]].decode("utf-8")
    if k["fmt"] == "md":
        order = [re.sub(r"^\d+\. ", "", line).lower() for line in doc.splitlines() if re.match(r"^\d+\. ", line)]
    else:
        order = [re.sub(r"^(First, |Then |Finally, )", "", line).rstrip(".").lower() for line in doc.splitlines()
                 if re.match(r"^(First, |Then |Finally, )", line)]
    stamped = []
    for line in files[k["log"]].decode("utf-8").splitlines():
        if line.startswith("{"):
            row = json.loads(line)
            stamped.append((row["ts"], row["msg"]))
        elif _ISO.match(line):
            stamped.append(_ISO.match(line).groups())
        else:
            mon, day, hms, msg = _SYSLOG.match(line).groups()
            months = "Jan Feb Mar Apr May Jun Jul Aug Sep Oct Nov Dec".split()
            stamped.append((f"{months.index(mon) + 1:02d}-{int(day):02d}T{hms}", msg))
    seen = [msg.lower() for _, msg in sorted(stamped) if msg.lower() in order]
    return order, seen


def truth_from_bytes(pair, files):
    kind = pair["kind"]
    if kind == "report_total":
        stated, values = read_report_total(pair, files)
        return stated == sum(values)
    if kind == "chart_series":
        plotted, tabled = read_chart(pair, files)
        span = max(tabled) - min(tabled)
        return len(plotted) == len(tabled) and all(abs(a - b) <= max(0.02 * span, 0.02 * abs(b))
                                                   for a, b in zip(plotted, tabled))
    if kind == "tones_rows":
        tones, rows = read_tones(pair, files)
        return tones == rows
    if kind == "mesh_bbox":
        stated, actual = read_mesh(pair, files)
        return all(abs(a - b) < 0.01 for a, b in zip(stated, actual))
    if kind == "code_trace":
        calls, edges, _ = read_trace(pair, files)
        return all(a in calls and b in calls and b in calls[a] for a, b in edges)
    order, seen = read_timeline(pair, files)
    return order == seen


# ---- the freeze ------------------------------------------------------------------------------------------------------

def test_cross_cases_and_generated_bytes_are_frozen():
    assert hashlib.sha256(Path(cross_cases.__file__).read_bytes()).hexdigest() == CROSS_CASES_SHA256
    for split in cross.SPLITS:
        assert cross.digest(split) == GENERATED_SHA256[split], split


def test_cross_generation_is_deterministic():
    assert [t.files for t in cross.tasks("development")] == [t.files for t in cross.tasks("development")]


def test_cross_counts_and_disjoint_splits():
    for split in cross.SPLITS:
        pairs = cross_cases.ALL[split]
        assert len(pairs) >= 36
        assert {p["kind"] for p in pairs} == set(cross.KINDS)
        assert all(sum(p["kind"] == k for p in pairs) >= 6 for k in cross.KINDS)
    dev, held = cross_cases.DEVELOPMENT, cross_cases.HELD_OUT
    assert not {p["seed"] for p in dev} & {p["seed"] for p in held}
    assert not {p["id"] for p in dev} & {p["id"] for p in held}
    assert not {json.dumps(p["knobs"], sort_keys=True) for p in dev} & \
        {json.dumps(p["knobs"], sort_keys=True) for p in held}


# ---- truth by construction, checked from the bytes ----------------------------------------------------------------------

@pytest.mark.parametrize("split", cross.SPLITS)
def test_cross_truth_is_what_the_bytes_say(split):
    pairs = _pairs(split)
    for task in cross.tasks(split):
        pair = pairs[task.id[:-1]]
        assert truth_from_bytes(pair, task.files) is task.truth, task.id


@pytest.mark.parametrize("split", cross.SPLITS)
def test_cross_twins_differ_in_exactly_one_value(split):
    pairs = _pairs(split)
    tasks = cross.tasks(split)
    for match, other in zip(tasks[::2], tasks[1::2]):
        pair = pairs[match.id[:-1]]
        assert match.truth and not other.truth and match.files.keys() == other.files.keys()
        kind = pair["kind"]
        if kind == "report_total":
            (s1, v1), (s2, v2) = read_report_total(pair, match.files), read_report_total(pair, other.files)
            diffs = (s1 != s2) + sum(a != b for a, b in zip(v1, v2)) + abs(len(v1) - len(v2))
        elif kind == "chart_series":
            (p1, t1), (p2, t2) = read_chart(pair, match.files), read_chart(pair, other.files)
            # the axis re-fits when a plotted value changes, so recovered values wobble by pixel rounding; the one
            # changed value moves by far more than that
            diffs = sum(abs(a - b) > 0.05 * max(1.0, abs(a)) for a, b in zip(p1 + t1, p2 + t2))
        elif kind == "tones_rows":
            (n1, r1), (n2, r2) = read_tones(pair, match.files), read_tones(pair, other.files)
            diffs = abs(n1 - n2) + abs(r1 - r2)
        elif kind == "mesh_bbox":
            k = pair["knobs"]
            a = match.files[k["obj"]].decode().splitlines() + match.files[k["readme"]].decode().splitlines()
            b = other.files[k["obj"]].decode().splitlines() + other.files[k["readme"]].decode().splitlines()
            changed = [(x, y) for x, y in zip(a, b) if x != y]
            diffs = len(changed)
            if diffs == 1:                                       # one line, and in it one number
                nums = [(u, v) for u, v in zip(re.findall(r"-?[0-9.]+", changed[0][0]),
                                               re.findall(r"-?[0-9.]+", changed[0][1])) if u != v]
                diffs = len(nums)
        elif kind == "code_trace":
            (c1, _, n1), (c2, _, n2) = read_trace(pair, match.files), read_trace(pair, other.files)
            assert c1 == c2 and len(n1) == len(n2)
            diffs = sum(x != y for x, y in zip(n1, n2))         # one call event, or one node of the call tree
        else:
            k = pair["knobs"]
            l1, l2 = match.files[k["log"]].decode().splitlines(), other.files[k["log"]].decode().splitlines()
            assert match.files[k["doc"]] == other.files[k["doc"]] and sorted(map(len, l1)) == sorted(map(len, l2))
            diffs = len(set(l1) ^ set(l2)) // 2                   # one event line re-stamped
        assert diffs == 1, (match.id, kind, diffs)


# ---- scoring ---------------------------------------------------------------------------------------------------------

@pytest.mark.parametrize("split", cross.SPLITS)
def test_cross_reference_scores(split):
    today = cross.score("today", split)
    assert today["answered"]["k"] == 0 and today["correct"]["k"] == 0
    yes = cross.score("always_consistent", split)
    no = cross.score("always_inconsistent", split)
    assert yes["correct"]["share"] == 0.5 and no["correct"]["share"] == 0.5
    assert yes["matching"]["correct"]["share"] == 1.0 and yes["non_matching"]["correct"]["share"] == 0.0
    assert yes["both_twins_correct"]["k"] == 0
    for kind in cross.KINDS:
        assert yes["by_kind"][kind]["correct"]["share"] == 0.5


@pytest.mark.parametrize("split", cross.SPLITS)
def test_cross_a_reader_from_the_bytes_scores_one(split):
    by_question = {p["question"]: p for p in cross_cases.ALL[split]}
    assert len(by_question) == len(cross_cases.ALL[split])

    def relate(files, question):
        pair = by_question[question]
        return {"answer": truth_from_bytes(pair, files), "because": ["read both files"]}
    result = cross.score(relate, split)
    assert result["correct"]["share"] == 1.0 and result["both_twins_correct"]["share"] == 1.0
    assert result["with_reasons"]["share"] == 1.0


def test_cross_non_boolean_answers_are_cannot():
    result = cross.score(lambda files, q: {"answer": "yes"}, "development")
    assert result["answered"]["k"] == 0
